insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values
  ('70a3d740-cbcd-5dc6-8706-55ab6afcd0f5', 'Paróquia da Catedral Diocesana. A Igreja de Nossa Senhora da Conceição, primeira igreja de Patos, pertence à paróquia.', '{"https://diocesedepatospb.org.br/paroquias/paroquia-nossa-senhora-da-guia/","https://diocesedepatospb.org.br/paroquias/paroquia-nossa-senhora-da-guia/","https://www.instagram.com/nsdaguiapatos/"}', 'alta'),
  ('9c937920-f1e1-54c6-811a-d0e94b0b0bd4', 'Sem horário achado. Perfil da paróquia no Instagram: paroquiadefatimapatos; a bio vista na busca diz que foi criada em 13/05/1962 por Dom Expedito. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/","https://www.instagram.com/paroquiadefatimapatos/"}', ''),
  ('4eb47c1c-5011-5206-a0b9-73d6689f6348', 'Criada em 1956. A Área Pastoral São Francisco, atendida por esta paróquia, está em item próprio.', '{"https://diocesedepatospb.org.br/paroquias/paroquia-santo-antonio/","https://diocesedepatospb.org.br/paroquias/paroquia-santo-antonio/"}', 'alta'),
  ('235d46a1-e15b-5e11-8d5b-64bf9729d592', 'Sem horário achado. Paróquia criada em 1962. Perfil no Instagram: paroquiasaosebastiaopatos (só o título apareceu na busca). Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/","https://www.instagram.com/paroquiasaosebastiaopatos/"}', ''),
  ('54303ebd-9d24-56c1-a546-1f9123254fd6', 'Sem horário achado. Perfil no Instagram: paroquiasaopedropatos, que a busca mostra como da Diocese de Patos.', '{"https://diocesedepatospb.org.br/foranias/","https://www.instagram.com/paroquiasaopedropatos/"}', ''),
  ('6efc67d8-4482-54d9-bd05-6f0a52aaaf53', 'Sem horário achado. A página de foranias da diocese confirma a unidade; busca na web e no Instagram não trouxe horário com fonte.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('a65124e0-7dbb-5308-9347-e337d47e75f5', 'Sem horário achado. Perfil no Instagram: paroquiadosagradopatos, que a busca mostra como da Diocese de Patos.', '{"https://diocesedepatospb.org.br/foranias/","https://www.instagram.com/paroquiadosagradopatos/"}', ''),
  ('57def79d-f7f9-5120-bea1-702d6a692135', 'Sem horário achado. A paróquia aparece só na página de foranias da diocese; buscas não trouxeram contato nem bairro. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('705ea1cf-4835-5523-8b4c-d3ae95fe97fe', 'Criada em 1981, desmembrada da Paróquia de Santo Antônio de Patos.', '{"https://diocesedepatospb.org.br/paroquias/paroquia-de-mae-dagua/","https://diocesedepatospb.org.br/paroquias/paroquia-de-mae-dagua/"}', 'alta'),
  ('a7b438cf-13ba-5e51-8026-46eae3a1ab20', 'Sem horário achado. A página de foranias da diocese confirma a unidade; busca na web e no Instagram não trouxe horário com fonte.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('3a24bd5c-177c-5d5b-8ab9-9a9af42e3dc2', 'Sem horário achado. Santa Terezinha é a padroeira do município; o anuário lista a paróquia no decanato das Espinharas. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('a384bff3-1991-5328-90fe-25a2949eac4a', 'Sem horário achado. A página de foranias da diocese confirma a unidade; busca na web e no Instagram não trouxe horário com fonte. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('42693f83-0e97-50ba-a4af-6455636b4656', 'Sem horário achado. O bairro Monte Castelo vem do perfil do administrador paroquial, visto na busca do Instagram.', '{"https://diocesedepatospb.org.br/foranias/","https://www.instagram.com/ronaldope__/"}', ''),
  ('c6837117-3411-5286-b0ba-c0eff99e2fbd', 'Atendida pela Paróquia de Santo Antônio de Patos; os horários saem da página daquela paróquia no site da diocese.', '{"https://diocesedepatospb.org.br/paroquias/paroquia-santo-antonio/","https://diocesedepatospb.org.br/foranias/"}', 'alta'),
  ('5d9e0546-8114-5ed3-8ce9-ba756a577be1', 'Sem horário achado. A página de foranias da diocese confirma a unidade; busca na web e no Instagram não trouxe horário com fonte. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('e222903e-c110-56f7-a564-879c0846ffd3', 'Sem horário achado. Paróquia criada em 1857. Perfil no Instagram: paroquiasantaluziapb. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/","https://www.instagram.com/paroquiasantaluziapb/"}', ''),
  ('a7c2fafe-714a-508b-92f9-76459c0ccb34', 'Sem horário achado. Paróquia criada em 2001; a festa do padroeiro é em janeiro. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('f9a0726b-a3a6-5f88-a7ad-db8885b6385c', 'Sem horário achado. A página de foranias da diocese confirma a unidade; busca na web e no Instagram não trouxe horário com fonte. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('e0ea792b-8b91-5a3a-a096-d93bbd9a4996', 'Sem horário achado. A página de foranias traz São Francisco; documento da Assembleia da Paraíba cita a Paróquia de São Francisco de Assis em Várzea. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('2ba3abd9-5bda-5ddb-82ed-ef95b72b96e3', 'Sem horário achado. O perfil psaojoseoperariosl aparece na busca como Paróquia São José Operário; a página de foranias ainda a traz como área pastoral.', '{"https://diocesedepatospb.org.br/foranias/","https://www.instagram.com/psaojoseoperariosl/"}', ''),
  ('bdf084a3-0b09-5f97-82d2-94651709a745', 'Sem horário achado. O anuário cita em Malta o Santuário de Deus Pai Todo Poderoso, não confirmado no site da diocese.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('901a5715-2f50-5e47-9ad7-d7564a773dd1', 'Sem horário achado. Paróquia criada em 1995. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('90eba404-51a0-5e53-9107-c4cf38081219', 'Criada em 2009. A página da diocese não traz missa dominical na matriz. Fora do formato: Missa quinzenal, sábado ou domingo, às 10h ou às 16h; Missa quinzenal, sábado ou domingo, às 10h ou às 16h; Missa quinzenal, sábado ou domingo, às 10h ou às 16h; Missa quinzenal, sábado ou domingo, às 10h ou às 16h; Missa quinzenal, sábado ou domingo, às 10h ou às 16h', '{"https://diocesedepatospb.org.br/paroquias/paroquia-nossa-senhora-do-desterro-vista-serrana-pb/","https://diocesedepatospb.org.br/paroquias/paroquia-nossa-senhora-do-desterro-vista-serrana-pb/"}', 'alta'),
  ('d118943f-34f0-52ba-8ff1-dd10b9c7f815', 'Criada em 1980, desmembrada da Paróquia de Santa Maria Madalena de Teixeira.', '{"https://diocesedepatospb.org.br/paroquias/paroquia-nossa-senhora-do-desterro-pb/","https://diocesedepatospb.org.br/paroquias/paroquia-nossa-senhora-do-desterro-pb/"}', 'alta'),
  ('c21c804a-f798-597b-a4b7-f96b116440d3', 'Sem horário achado. Uma das paróquias mais antigas da região; a festa da padroeira é patrimônio cultural do estado. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('f7c228ac-4d9f-57f5-8214-361b6a5b68ac', 'Fundada em 1951. A página de foranias a chama de Paróquia da Imaculada Conceição de Maria. Fora do formato: Missas às segundas e aos sábados, 19h, nas capelas da sede; confissões às quintas-feiras Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/paroquias/paroquia-nossa-senhora-da-conceicao-imaculada-pb/","https://diocesedepatospb.org.br/paroquias/paroquia-nossa-senhora-da-conceicao-imaculada-pb/"}', 'alta'),
  ('65c673dc-a2ba-5641-ad8f-7e237cc7dcb3', 'Sem horário achado. Paróquia criada em 2009. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('37ba1a19-73bb-5c08-8bfb-26289004148b', 'Criada em 2018, nas comemorações dos 60 anos da diocese. Fora do formato: Missas às segundas, terças e sábados, 17h, nas comunidades rurais', '{"https://diocesedepatospb.org.br/paroquias/paroquia-sao-jose-cacimbas-pb/","https://diocesedepatospb.org.br/paroquias/paroquia-sao-jose-cacimbas-pb/"}', 'alta'),
  ('daf60796-c72e-53bc-a123-1aecc5254241', 'Sem horário achado. A festa da padroeira é em dezembro. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('c8a7b4f6-d36e-51b6-acfa-bd07299a456d', 'Sem horário achado. A paróquia aparece só na página de foranias da diocese; não consta no anuário de 2026. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('572d330a-1eb8-593d-a08e-e6859002ec84', 'Criada em 1968. A matriz está em reforma desde 2018. Fora do formato: Missas nas comunidades rurais durante todo o mês Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/paroquias/paroquia-sao-miguel-arcanjo/"}', 'alta'),
  ('c35937a4-974d-56a4-ab8d-3e053ca82894', 'Sem horário achado. A página de foranias da diocese confirma a unidade; busca na web e no Instagram não trouxe horário com fonte. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('84c029e7-6ec7-5bec-8c6b-d3d40f2ee234', 'Sem horário achado. A página de foranias traz Nossa Senhora das Dores, mas o IBGE e o anuário dão o Divino Espírito Santo como padroeiro, com a paróquia criada em 1887. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/","https://gcatholic.org/churches/brazil/57612"}', ''),
  ('f270df95-733b-536b-ae94-a75cb03448d8', 'Instalada em 1967. Em 2019 a Paróquia de Santa Teresinha do Menino Jesus, em Emas, foi desmembrada dela. Fora do formato: Domingo, 16h, missa nas comunidades rurais Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/paroquias/paroquia-sao-sebastiao/","https://diocesedepatospb.org.br/paroquias/paroquia-sao-sebastiao/"}', 'alta'),
  ('da0290d1-2ab4-53db-933e-9863a256051f', 'Sem horário achado. São João Batista é padroeiro do município, um dos três da Paraíba com esse padroeiro. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('13acbb59-f282-515c-b1cf-63e02e0c320d', 'Sem horário achado; a página da paróquia no site da diocese só traz a história. Freguesia criada em 1739. A primeira igreja, dedicada a Nossa Senhora do Rosário em 2014, segue em uso.', '{"https://diocesedepatospb.org.br/paroquias/paroquia-santo-antonio-de-pianco/","https://diocesedepatospb.org.br/foranias/"}', ''),
  ('9d89b358-2907-506b-bc4c-1b86179fdcb4', 'A igreja antiga da cidade, dedicada a São Sebastião, copadroeiro do município, segue em funcionamento. Fora do formato: Missa uma vez por mês nos distritos de Serra Branca e Palestina', '{"https://diocesedepatospb.org.br/paroquias/paroquia-de-senhora-santana/","https://diocesedepatospb.org.br/paroquias/paroquia-de-senhora-santana/"}', 'alta'),
  ('6f4765ea-6084-5eb6-bce6-53401c5d1ae3', 'Paróquia desde 1965. Fora do formato: Segunda, 19h, missa nos setores de missão da zona urbana; Missa quinzenal na terça, 19h; Missa quinzenal na sexta, 18h, alternando com Várzea da Cruz; Missa quinzenal na sexta, 18h, alternando com São Domingos; Missa quinzenal no sábado, 16h', '{"https://diocesedepatospb.org.br/paroquias/paroquia-nossa-senhora-dos-remedios-nova-olinda-pb/","https://diocesedepatospb.org.br/paroquias/paroquia-nossa-senhora-dos-remedios-nova-olinda-pb/"}', 'alta'),
  ('c4c2d102-e696-5ecc-ab63-1f62b70f067d', 'Sem horário achado. Criada em 2019 como a 40ª paróquia da diocese, desmembrada da Paróquia de São Sebastião de Catingueira; falta na página de foranias, mas a página da Paróquia de Piancó a lista na Forania do Piancó. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/paroquias/paroquia-sao-sebastiao/","https://diocesedepatospb.org.br/paroquias/paroquia-santo-antonio-de-pianco/"}', ''),
  ('fa1bf079-1dd9-5d4d-8598-e81fbe4f684f', 'Sem horário achado. A página de foranias da diocese confirma a unidade; busca na web e no Instagram não trouxe horário com fonte. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('db772d8f-6d4a-5378-897f-a1cd187b2eef', 'Sem horário achado. A página de foranias da diocese confirma a unidade; busca na web e no Instagram não trouxe horário com fonte. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedepatospb.org.br/foranias/"}', ''),
  ('5c9ca47e-5779-5a9d-9190-f6536165fdb1', 'Criada em 2008. Abrange Assunção e Salgadinho.', '{"https://diocesedepatospb.org.br/paroquias/paroquia-nossa-senhora-da-assuncao/","https://diocesedepatospb.org.br/paroquias/paroquia-nossa-senhora-da-assuncao/"}', 'alta')
